import{_ as p,a0 as r,w as o,s as d,ao as l,I as t,a1 as n,A as i,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04","title":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器","tag":"201708","desc":""},"relativePath":"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04.md","filePath":"[post].md"}'),c={name:"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04.md"};function h(g,s,b,u,k,f){const a=r("Link");return o(),d("div",null,[s[17]||(s[17]=l('<h1 id="如何保护-ubuntu-16-04-上的-nginx-web-服务器" tabindex="-1">如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 <a class="header-anchor" href="#如何保护-ubuntu-16-04-上的-nginx-web-服务器" aria-label="Permalink to “如何保护 Ubuntu 16.04 上的 NGINX Web 服务器”">​</a></h1><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/le-logo-standard.png" alt="Let&#39;s Encrypt Encryption CA" title="le-logo-standard"></p><h3 id="什么是-let-s-encrypt" tabindex="-1">什么是 Let’s Encrypt <a class="header-anchor" href="#什么是-let-s-encrypt" aria-label="Permalink to “什么是 Let’s Encrypt”">​</a></h3>',3)),t("p",null,[n(a,{href:"https://letsencrypt.org/"},{default:i(()=>[...s[0]||(s[0]=[e("Let’s Encrypt",-1)])]),_:1}),s[2]||(s[2]=e(" 是互联网安全研究组织 （ISRG） 提供的免费证书认证机构。它提供了一种轻松自动的方式来获取免费的 SSL/TLS 证书 - 这是在 Web 服务器上启用加密和 HTTPS 流量的必要步骤。获取和安装证书的大多数步骤可以通过使用名为 ",-1)),n(a,{href:"https://certbot.eff.org/"},{default:i(()=>[...s[1]||(s[1]=[e("Certbot",-1)])]),_:1}),s[3]||(s[3]=e(" 的工具进行自动化。",-1))]),s[18]||(s[18]=l(`<p>特别地，该软件可在可以使用 shell 的服务器上使用：换句话说，它可以通过 SSH 连接使用。</p><p>在本教程中，我们将看到如何使用 <code>certbot</code> 获取免费的 SSL 证书，并在 Ubuntu 16.04 服务器上使用 Nginx。</p><h3 id="安装-certbot" tabindex="-1">安装 Certbot <a class="header-anchor" href="#安装-certbot" aria-label="Permalink to “安装 Certbot”">​</a></h3><p>第一步是安装 <code>certbot</code>，该软件客户端可以几乎自动化所有的过程。 Certbot 开发人员维护自己的 Ubuntu 仓库，其中包含比 Ubuntu 仓库中存在的软件更新的软件。</p><p>添加 Certbot 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># add-apt-repository ppa:certbot/certbot</span></span></code></pre></div><p>接下来，更新 APT 源列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get update</span></span></code></pre></div><p>此时，可以使用以下 <code>apt</code> 命令安装 <code>certbot</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install certbot</span></span></code></pre></div><p>Certbot 现已安装并可使用。</p><h3 id="获得证书" tabindex="-1">获得证书 <a class="header-anchor" href="#获得证书" aria-label="Permalink to “获得证书”">​</a></h3><p>有各种 Certbot 插件可用于获取 SSL 证书。这些插件有助于获取证书，而证书的安装和 Web 服务器配置都留给管理员。</p><p>我们使用一个名为 <strong>Webroot</strong> 的插件来获取 SSL 证书。</p><p>在有能力修改正在提供的内容的情况下，建议使用此插件。在证书颁发过程中不需要停止 Web 服务器。</p><h4 id="配置-nginx" tabindex="-1">配置 NGINX <a class="header-anchor" href="#配置-nginx" aria-label="Permalink to “配置 NGINX”">​</a></h4><p>Webroot 会在 Web 根目录下的 <code>.well-known</code> 目录中为每个域创建一个临时文件。在我们的例子中，Web 根目录是 <code>/var/www/html</code>。确保该目录在 Let’s Encrypt 验证时可访问。为此，请编辑 NGINX 配置。使用文本编辑器打开 <code>/etc/nginx/sites-available/default</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/nginx/sites-available/default</span></span></code></pre></div><p>在该文件中，在 <code>server</code> 块内，输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> location ~ /.well-known {</span></span>
<span class="line"><span>    allow all;</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>保存，退出并检查 NGINX 配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nginx -t</span></span></code></pre></div><p>没有错误的话应该会显示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nginx: the configuration file /etc/nginx/nginx.conf syntax is ok</span></span>
<span class="line"><span>nginx: configuration file /etc/nginx/nginx.conf test is successful</span></span></code></pre></div><p>重启 NGINX：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart nginx</span></span></code></pre></div><h4 id="使用-certbot-获取证书" tabindex="-1">使用 Certbot 获取证书 <a class="header-anchor" href="#使用-certbot-获取证书" aria-label="Permalink to “使用 Certbot 获取证书”">​</a></h4><p>下一步是使用 Certbot 的 Webroot 插件获取新证书。在本教程中，我们将保护示例域 www.example.com。需要指定应由证书保护的每个域。执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># certbot certonly --webroot --webroot-path=/var/www/html -d www.example.com</span></span></code></pre></div><p>在此过程中，Cerbot 将询问有效的电子邮件地址，用于进行通知。还会要求与 EFF 分享，但这不是必需的。在同意服务条款之后，它将获得一个新的证书。</p><p>最后，目录 <code>/etc/letsencrypt/archive</code> 将包含以下文件：</p><ul><li><code>chain.pem</code>：Let’s Encrypt 加密链证书。</li><li><code>cert.pem</code>：域名证书。</li><li><code>fullchain.pem</code>：<code>cert.pem</code>和 <code>chain.pem</code> 的组合。</li><li><code>privkey.pem</code>：证书的私钥。</li></ul><p>Certbot 还将创建符号链接到 <code>/etc/letsencrypt/live/domain_name/</code> 中的最新证书文件。这是我们将在服务器配置中使用的路径。</p><h3 id="在-nginx-上配置-ssl-tls" tabindex="-1">在 NGINX 上配置 SSL/TLS <a class="header-anchor" href="#在-nginx-上配置-ssl-tls" aria-label="Permalink to “在 NGINX 上配置 SSL/TLS”">​</a></h3><p>下一步是服务器配置。在 <code>/etc/nginx/snippets/</code> 中创建一个新的代码段。 <strong>snippet</strong> 是指一段配置，可以包含在虚拟主机配置文件中。如下创建一个新的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/nginx/snippets/secure-example.conf</span></span></code></pre></div><p>该文件的内容将指定证书和密钥位置。粘贴以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssl_certificate /etc/letsencrypt/live/domain_name/fullchain.pem;</span></span>
<span class="line"><span>ssl_certificate_key /etc/letsencrypt/live/domain_name/privkey.pem;</span></span></code></pre></div><p>在我们的例子中，<code>domain_name</code> 是 <code>example.com</code>。</p><h4 id="编辑-nginx-配置" tabindex="-1">编辑 NGINX 配置 <a class="header-anchor" href="#编辑-nginx-配置" aria-label="Permalink to “编辑 NGINX 配置”">​</a></h4><p>编辑默认虚拟主机文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/nginx/sites-available/default</span></span></code></pre></div><p>如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server {</span></span>
<span class="line"><span> listen 80 default_server;</span></span>
<span class="line"><span> listen [::]:80 default_server;</span></span>
<span class="line"><span> server_name www.example.com</span></span>
<span class="line"><span> return 301 https://$server_name$request_uri;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # SSL configuration</span></span>
<span class="line"><span> #</span></span>
<span class="line"><span> listen 443 ssl default_server;</span></span>
<span class="line"><span> listen [::]:443 ssl default_server;</span></span>
<span class="line"><span> include snippets/secure-example.conf</span></span>
<span class="line"><span> #</span></span>
<span class="line"><span> # Note: You should disable gzip for SSL traffic.</span></span>
<span class="line"><span> # See: https://bugs.debian.org/773332</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这将启用 NGINX 加密功能。</p><p>保存、退出并检查 NGINX 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nginx -t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nginx: the configuration file /etc/nginx/nginx.conf syntax is ok</span></span>
<span class="line"><span>nginx: configuration file /etc/nginx/nginx.conf test is successful</span></span></code></pre></div><p>重启 NGINX：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart nginx</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>按照上述步骤，此时我们已经拥有了一个安全的基于 NGINX 的 Web 服务器，它由 Certbot 和 Let’s Encrypt 提供加密。这只是一个基本配置，当然你可以使用许多 NGINX 配置参数来个性化所有东西，但这取决于特定的 Web 服务器要求。</p><hr>`,52)),t("p",null,[s[5]||(s[5]=e("via: ",-1)),n(a,{href:"https://www.unixmen.com/encryption-secure-nginx-web-server-ubuntu-16-04/"},{default:i(()=>[...s[4]||(s[4]=[e("https://www.unixmen.com/encryption-secure-nginx-web-server-ubuntu-16-04/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://www.unixmen.com/author/tutan/"},{default:i(()=>[...s[6]||(s[6]=[e("Giuseppe Molica",-1)])]),_:1}),s[10]||(s[10]=e(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[11]||(s[11]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[13]||(s[13]=[e("Linux中国",-1)])]),_:1}),s[16]||(s[16]=e(" 荣誉推出",-1))])])}const C=p(c,[["render",h]]);export{y as __pageData,C as default};
